const HTML = [];
const HEADINGS = [];
const usedIds = new Set();
const emit = (s) => { HTML.push(s); };
const esc = (s) => String(s === undefined || s === null ? "" : s)
  .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const bareSlug = (s) => String(s).toLowerCase().replace(/[^a-z0-9]+/g, "-")
  .replace(/^-+|-+$/g, "") || "s";
const slug = (s) => {
  let base = String(s).toLowerCase().replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "") || "s";
  let id = base, n = 2;
  while (usedIds.has(id)) { id = base + "-" + (n++); }
  usedIds.add(id);
  return id;
};
// Runs carry their own HTML so paragraph helpers can assemble children.
const withHtml = (run, html) => { run.__html = html; return run; };
const runHtml = (r) =>
  (r && r.__html !== undefined) ? r.__html : (typeof r === "string" ? esc(r) : "");
const kidsHtml = (runs) =>
  Array.isArray(runs) ? runs.map(runHtml).join("") : esc(runs);
const cellHtml = (txt, o = {}) =>
  `<td${o.head ? ' class="bk-th"' : ""}>${esc(txt)}</td>`;
const tableHtml = (headCells, bodyRows) => {
  const th = headCells === null ? "" :
    `<thead><tr>${headCells.map(h => `<th>${esc(h)}</th>`).join("")}</tr></thead>`;
  const tb = bodyRows.map(r =>
    `<tr>${r.map(c => `<td>${esc(c)}</td>`).join("")}</tr>`).join("");
  emit(`<table class="bk-tbl">${th}<tbody>${tb}</tbody></table>`);
};

