// [DOCTRINE_INDEX_V1] The appendix is GENERATED, not written. A hand-kept index
// of two hundred rules is wrong within a week, and the entire claim it makes is
// that it cannot drift: every tag in this book appears verbatim in the source,
// and checksite.py fails the build if a load-bearing one is removed. So it is
// read off the tree at build time, or it is not trustworthy enough to print.
//
// FROGNET_SRC points at a source tree. If none is found the appendix says so
// plainly rather than emitting a stale table -- an index that quietly falls
// back to yesterday's answer is the thing it exists to prevent.
const doctrineScan = () => {
  const roots = [ process.env.FROGNET_SRC,
                  "../etc/frognet_bundles/communicator",
                  "/etc/frognet_bundles/communicator" ].filter(Boolean);
  const root = roots.find((d) => { try { return fs.statSync(d).isDirectory(); }
                                   catch (e) { return false; } });
  if (!root) return null;
  const hits = new Map();
  for (const f of fs.readdirSync(root)) {
    // .sh as well as .py: three rules live in the build scripts, and a
    // scanner that only reads Python reports them as missing from the source
    // when they are merely missing from the filter.
    if (!f.endsWith(".py") && !f.endsWith(".sh")) continue;
    let src; try { src = fs.readFileSync(root + "/" + f, "utf8"); }
    catch (e) { continue; }
    const m = src.match(/\[[A-Z][A-Z0-9_]*_V[0-9]+\]/g) || [];
    for (const raw of m) {
      const tag = raw.slice(1, -1);
      if (!hits.has(tag)) hits.set(tag, new Map());
      const per = hits.get(tag);
      per.set(f, (per.get(f) || 0) + 1);
    }
  }
  return { root, hits };
};

